/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        propName: 'nativeTranslationValue',
        value: event.payload.value
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const value = event.payload.value;
    if (value === true) {
        return {
            propName: 'showNTOnAlert',
            value: true
        };
    }

}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const value = event.payload.value;
    /*
    if (value === true) {
        return {
            propName: 'showDTOnAlert',
            value: true
        };
    }
    */

    return {
        propName: 'showDTOnAlert',
        value: value
    };

}

