/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	var val = [];
	if (api.state.dtShowMoreClicked){
		val = api.data.languages_configured_for_dt.output.slice(0,16);
	}
	else val = api.data.languages_configured_for_dt.output;

	return {
		propName: "Languages",
		value: val
	};
}

